                     sprite_flags & RENDER_SCENE_MASK) != 0) {
                    if ((sprite_flags & SPRITE_FLAG_ACTIVE) != 0 &&
                        (sprite_flags & SPRITE_FLAG_RENDER_ENABLED) != 0 &&
                        (sprite_flags & SPRITE_FLAG_DELAYED_RENDER) == 0) {
                        Vector3 projected = sprite->position;
