                                if (cursor == 0) {
                                    previous->next = node;
                                    node->next = 0;
                                } else if (previous != 0) {
                                    previous->next = node;
                                    node->next = cursor;
                                } else {
                                    node->next = cursor;
                                    g_sprite_depth_buckets[bucket_index] = node;
                                }
                            } else {
                                g_sprite_depth_buckets[bucket_index] = node;
                                node->next = 0;
                            }

