                post_sprite_count = 0;
                RenderableBod* bod =
                    (RenderableBod*)active_bod_list.first;
                RenderableBod** post_cursor = g_post_sprite_bods;
                while (bod != 0) {
                    if ((bod->list_flags & BOD_FLAG_DEBUG) != 0) {
                        debug_report_stub("DEBUG RENDER\n");
                    }

