from pathlib import Path
import json,difflib,itertools,re
from snail import match as m
p=Path('tools/match/scratches/render_game_frame');out=Path('/tmp/snail-goal-render-frame-owners');out.mkdir(exist_ok=True);cfg=m.load_scratch_config(p);baseline=(p/'scratch.cpp').read_text()
def evaluate(forms,group):
 rows=[]
 for label,source in forms.items():
  results=[];st=m.scratch_status_payload(m.evaluate_source_overlay(cfg,source,on_match=results.append));rows.append({'label':label,**st});print(label,round((st['match_ratio'] or 0)*100,8),st['candidate_instructions'],st['prefix_instructions'],st['references'],st['error'],flush=True);(out/(label+'.cpp')).write_text(source)
  if results:
   r=results[0];(out/(label+'.diff')).write_text('\n'.join(difflib.unified_diff(r.target_lines,r.candidate_lines,n=3)));(out/(label+'-code.json')).write_text(json.dumps({'target':[{'offset':i.offset,'text':i.text} for i in r.target_disassembly],'candidate':[{'offset':i.offset,'text':i.text} for i in r.candidate_disassembly],'audit':m._masked_audit_cache_payload(r.masked_operand_audit),'frame':m.stack_frame_diagnostic_payload(r)},indent=2))
  (out/(group+'-results.json')).write_text(json.dumps(rows,indent=2)+'\n')
 return rows
if __name__=='__main__':evaluate({'baseline':baseline},'baseline')

