'index-do':'''                                int shift = CAMERA_LAST_INDEX;
                                do {
                                    camera_order[shift] = camera_order[shift - 1];
                                    --shift;
                                } while (shift > insert);''',
'pointer-end':'''                                int* shift = &camera_order[CAMERA_LAST_INDEX];
                                int* stop = &camera_order[insert];
                                do {
                                    *shift = shift[-1];
                                    --shift;
                                } while (shift != stop);''',
'index-count':'''                                int shift = CAMERA_LAST_INDEX;
