 forms['replay-'+pos]=baseline[:start]+b+baseline[end:]
 for pointer in ['cursor','index']:
  bb=b.replace('RenderableBod* bod = *post_cursor;\n                    unsigned int bod_flags = bod->list_flags;', 'unsigned int bod_flags = (*post_cursor)->list_flags;').replace('bod->','(*post_cursor)->')
  if pointer=='index':
   bb=bb.replace('RenderableBod** post_cursor =\n                    g_post_sprite_bods + replay_count;\n','').replace('--post_cursor;','--replay_count;').replace('(*post_cursor)', 'g_post_sprite_bods[replay_count]').replace('                    --replay_count;\n                } while', '                } while')
  forms['replay-'+pos+'-'+pointer]=baseline[:start]+bb+baseline[end:]
evaluate(forms,'controls')

